insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$what-is-ipfx$q$,$q$company$q$,$q$What is IPFX Capital?$q$,array[$q$what is ipfx$q$,$q$who are you$q$,$q$about ipfx$q$,$q$about the company$q$,$q$what do you do$q$,$q$tell me about ipfx$q$,$q$prop firm$q$,$q$proprietary trading firm$q$,$q$who is ipfx$q$,$q$what is this$q$]::text[],$q$IPFX Capital Ltd is a UK-based proprietary trading firm (founded 2025, London) that runs trader evaluation programmes. You trade a simulated evaluation account on **IPFX Markets**, our trading platform. If you meet the rules you can progress to a funded account and earn a share of the profit — up to **{{p:trad_25k_p1.split_pct}}**.

We offer four programmes: the free **Infinity Challenge**, the **Traditional Challenge**, the **Futures Challenge** and the **Personalised Application Challenge (PAC)**. Ask me about any of them, or see the [About page](/about.html).$q$,array[$q$How does it work?$q$,$q$Which programmes do you offer?$q$,$q$Is IPFX regulated?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$how-it-works$q$,$q$company$q$,$q$How does IPFX work?$q$,array[$q$how does it work$q$,$q$how does ipfx work$q$,$q$how it works$q$,$q$process$q$,$q$steps$q$,$q$how do i get funded$q$,$q$walk me through$q$,$q$overview$q$]::text[],$q$1. **Create an account** and verify your email.
2. **Choose a programme** and submit an application (identity details and documents).
3. **Our team reviews it** — {{c:review_time}}. Nothing is charged and no account is created until you're approved.
4. **Trade on IPFX Markets.** The Infinity Challenge is free; Traditional and Futures are paid after approval.
5. **Meet the rules** (profit target, drawdown and daily loss limits, minimum days).
6. **Get funded** and request payouts — you keep {{p:trad_25k_p1.split_pct}} of the profit.

Evaluation accounts use virtual capital. Ask me for detail on any step.$q$,array[$q$How do I start?$q$,$q$What do I need to apply?$q$,$q$How do payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$programmes-overview$q$,$q$company$q$,$q$Which programmes do you offer?$q$,array[$q$programmes$q$,$q$programs$q$,$q$challenges$q$,$q$what challenges$q$,$q$types of challenge$q$,$q$which challenge$q$,$q$options$q$,$q$products$q$,$q$what do you offer$q$,$q$list of challenges$q$,$q$what exactly do you offer$q$,$q$what services$q$]::text[],$q$- **[Infinity Challenge](/infinity.html)** — free to start, four stages from a $1,000 evaluation account to a professional funded account.
- **[Traditional Challenge](/start-challenge.html)** — {{p:trad_25k_p1.target_pct}} / {{p:trad_25k_p2.target_pct}} / {{p:trad_25k_p3.target_pct}} targets over three phases. Fees: {{fees:traditional}}.
- **[Futures Challenge](/futures.html)** — two phases ({{p:fut_25k_p1.target_pct}} then {{p:fut_25k_p2.target_pct}}), end-of-day trailing drawdown. Fees: {{fees:futures}}.
- **[Personalised Application Challenge (PAC)](/personalised-challenge.html)** — you disclose your strategy, our analysts backtest it and agree custom parameters. Entry fees: {{fees:pac}}.

All programmes need an approved application. Which would you like to know more about?$q$,array[$q$Tell me about the Infinity Challenge$q$,$q$Traditional Challenge rules$q$,$q$What is the PAC?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$which-programme$q$,$q$company$q$,$q$Which programme should I choose?$q$,array[$q$which challenge is best$q$,$q$which programme should i choose$q$,$q$which one should i pick$q$,$q$infinity vs traditional$q$,$q$difference between challenges$q$,$q$compare challenges$q$,$q$best challenge$q$,$q$recommend a challenge$q$,$q$which is better$q$,$q$which challenge should i pick$q$,$q$which challenge should i choose$q$,$q$which one should i choose$q$,$q$what should i start with$q$]::text[],$q$I can't recommend one for your circumstances, but here's how they differ:

- **Infinity** — no fee, small starting capital ($1,000), four stages, stricter trade-level rules (1% risk per trade, daily profit cap in Stage 1).
- **Traditional** — paid, larger simulated accounts ($10K–$200K), three phases with static drawdown.
- **Futures** — paid, two phases, end-of-day trailing drawdown, aimed at CME futures traders.
- **PAC** — for traders who already have a documented, profitable strategy; custom parameters agreed with our analysts.

Compare the exact numbers with "What are the fees?" or "Compare the daily loss limits". Trading is risky and none of this is financial advice.$q$,array[$q$What are the fees?$q$,$q$Compare the drawdown rules$q$,$q$Is the Infinity Challenge really free?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$regulation$q$,$q$company$q$,$q$Is IPFX regulated by the FCA?$q$,array[$q$regulated$q$,$q$fca$q$,$q$are you regulated$q$,$q$licensed$q$,$q$authorised$q$,$q$regulation$q$,$q$financial conduct authority$q$,$q$compliance status$q$]::text[],$q$No. IPFX Capital Ltd is **not authorised or regulated by the Financial Conduct Authority (FCA)** or any other financial regulator. We do not provide investment advice, and we sell an evaluation service rather than a regulated financial product. See section 2 of our [Terms](/terms.html) and the [Risk Disclosure](/risk-disclosure.html).$q$,array[$q$Is it real money?$q$,$q$What is the Risk Disclosure?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$real-money$q$,$q$company$q$,$q$Is it real money or a demo?$q$,array[$q$real money$q$,$q$demo account$q$,$q$simulated$q$,$q$virtual capital$q$,$q$is it a demo$q$,$q$do i trade real money$q$,$q$live account$q$,$q$own money$q$,$q$deposit$q$,$q$risk my money$q$]::text[],$q$- **Evaluation accounts are simulated** with virtual capital. None of your own money is placed in a market.
- The **challenge fee** (where there is one) pays for the evaluation service — it isn't a deposit or balance you can withdraw.
- **Funded accounts are owned by IPFX.** You never deposit into them; you trade the company's account under the agreed rules and receive a discretionary profit split.
- **Infinity Stage 4** is described as trading on live markets (A-book).

Prices on IPFX Markets are for simulated evaluation and may differ from live market prices. See sections 2 and 9 of the [Terms](/terms.html).$q$,array[$q$How do payouts work?$q$,$q$What is the profit split?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$legit-safe$q$,$q$company$q$,$q$Is IPFX legit? Can I trust IPFX?$q$,array[$q$is ipfx legit$q$,$q$is this a scam$q$,$q$can i trust$q$,$q$trustworthy$q$,$q$is it safe$q$,$q$is ipfx safe$q$,$q$fraud$q$,$q$fake company$q$,$q$real company$q$,$q$reviews$q$,$q$trustpilot$q$,$q$reputation$q$,$q$is this legit$q$,$q$is it legit$q$,$q$are you legit$q$,$q$is this real$q$,$q$is this a proper company$q$,$q$is ipfx a real company$q$,$q$is this a real company$q$,$q$proper company$q$]::text[],$q$I can only give you facts rather than reassurance:

- IPFX Capital Ltd is registered in England & Wales and launched in 2025, so we're a young firm.
- Our [Terms](/terms.html), [Privacy Policy](/privacy.html) and [Risk Disclosure](/risk-disclosure.html) are public — please read them before you apply.
- We are **not FCA regulated**, and passing a challenge, getting funded or being paid is never guaranteed.
- Never pay anyone claiming to be IPFX outside our website checkout, and never share your password.

Only spend what you can afford to lose. You can leave an honest review on [Trustpilot](https://www.trustpilot.com/evaluate/ipfxcapital.com); we never pay or reward anyone for reviews.$q$,array[$q$Is IPFX regulated?$q$,$q$Is the fee refundable?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$team-founders$q$,$q$company$q$,$q$Who runs IPFX? Who founded it?$q$,array[$q$who founded$q$,$q$founder$q$,$q$ceo$q$,$q$who runs ipfx$q$,$q$who owns ipfx$q$,$q$the team$q$,$q$who is behind ipfx$q$,$q$paul adeniji$q$,$q$management$q$,$q$where are you based$q$,$q$headquarters$q$,$q$location$q$,$q$uk company$q$,$q$where is ipfx located$q$,$q$where are you located$q$,$q$company address$q$,$q$registered address$q$,$q$office address$q$,$q$company number$q$,$q$registration number$q$,$q$companies house$q$,$q$when did you start$q$,$q$when were you founded$q$,$q$how old is the company$q$,$q$founded in$q$,$q$year founded$q$,$q$is ipfx based in the uk$q$]::text[],$q$IPFX Capital was founded in 2025 by a team of traders, analysts and operators, based in London. Paul Adeniji is Co-Founder & CEO. The [About page](/about.html) describes the team (trading, quant & risk, technology, compliance & operations). I can't share personal contact details for team members — please use {{c:contact_email}}.

Our registered company number and registered-office address haven't been published on the website yet — if you need them, email {{c:contact_email}}.$q$,array[$q$How do I contact IPFX?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$how-to-start$q$,$q$getting-started$q$,$q$How do I start a challenge?$q$,array[$q$how do i start$q$,$q$get started$q$,$q$sign up$q$,$q$signup$q$,$q$create an account$q$,$q$register$q$,$q$begin$q$,$q$start a challenge$q$,$q$join$q$,$q$how to apply$q$,$q$start trading$q$,$q$onboarding$q$]::text[],$q${{c:launch_short}}

When applications are open:

1. [Create an account](/signup.html) and confirm the verification email.
2. Go to [Start a Challenge](/start-challenge.html) (or the [Infinity page](/infinity.html) for the free challenge) and pick your programme.
3. Complete the application: personal details, a few questions, and your ID + proof of address.
4. Wait for our review — {{c:review_time}}. You'll be emailed the decision.
5. If approved: Infinity opens in your dashboard; Traditional/Futures move to payment; PAC waits for the team to confirm the next step.

{{c:checkout_note}}$q$,array[$q$What do I need to apply?$q$,$q$How long does approval take?$q$,$q$Is the Infinity Challenge free?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$application-requirements$q$,$q$getting-started$q$,$q$What do I need to apply?$q$,array[$q$what do i need$q$,$q$requirements$q$,$q$documents needed$q$,$q$what documents$q$,$q$application requirements$q$,$q$eligibility$q$,$q$am i eligible$q$,$q$who can join$q$,$q$what information$q$,$q$application form$q$,$q$what documents do i need to apply$q$]::text[],$q$To apply you need:
- a **verified email address** and to be **18 or over**
- your legal name, date of birth, phone number, address and nationality
- your occupation, source of funds and expected trading activity, and a politically-exposed-person declaration
- a valid, unexpired **photo ID** (passport, driving licence or national ID card)
- **proof of address** dated within the last 3 months (utility bill, bank statement or official letter)
- acceptance of the Terms, Risk Disclosure and a few declarations

Every application is reviewed by a person. See "Is my ID safe?" for how we protect your documents.$q$,array[$q$Is my ID safe?$q$,$q$How long does approval take?$q$,$q$Which countries are restricted?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$approval-time$q$,$q$getting-started$q$,$q$How long does approval take? Why is approval needed?$q$,array[$q$approval$q$,$q$approved$q$,$q$review time$q$,$q$manual approval$q$,$q$why approval$q$,$q$when will i hear$q$,$q$pending$q$,$q$under review$q$,$q$application received$q$,$q$how long does approval take$q$,$q$how long is approval$q$,$q$how long is kyc$q$,$q$how long does kyc take$q$,$q$how long does verification take$q$,$q$waiting for approval$q$,$q$when will i hear back$q$]::text[],$q$Every challenge application is reviewed by a member of our team, who decides Yes or No. We aim to decide **{{c:review_time}}** (the PAC's strategy review takes {{c:pac_review_time}}).

Until you're approved, **no payment is requested and no trading account is created**. Automated checks may flag issues for a person to look at, but they never make the final decision.

I can't see your individual application — if it's taking longer, email {{c:contact_email}} from your registered email address.$q$,array[$q$What if my application is denied?$q$,$q$What do I need to apply?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$application-denied$q$,$q$getting-started$q$,$q$What if my application is denied?$q$,array[$q$denied$q$,$q$rejected$q$,$q$not approved$q$,$q$declined$q$,$q$application denied$q$,$q$why was i denied$q$,$q$appeal$q$,$q$reconsider$q$,$q$turned down$q$]::text[],$q$You'll see the decision (and a note where one is given) in your application status and by email. You can ask us to explain or reconsider a decision by emailing {{c:contact_email}}. Because I can't see individual applications, I can't tell you why a specific one was denied.$q$,array[$q$How do I contact IPFX?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$kyc-documents$q$,$q$getting-started$q$,$q$What ID and documents do you accept? How does identity verification work?$q$,array[$q$kyc$q$,$q$id verification$q$,$q$identity$q$,$q$upload documents$q$,$q$proof of address$q$,$q$passport$q$,$q$driving licence$q$,$q$national id$q$,$q$what id$q$,$q$selfie$q$,$q$utility bill$q$,$q$bank statement$q$,$q$verify my identity$q$,$q$documents rejected$q$,$q$what documents do i need to upload$q$,$q$proof of address requirements$q$,$q$what id do you accept$q$]::text[],$q$We accept:
- **Photo ID:** passport, driving licence or national identity card — valid and not expired
- **Proof of address:** utility bill, bank statement or official government letter dated within the last **3 months**

You upload them as part of your application (and can update them from your dashboard). Our team reviews them; if something is unclear or rejected you'll be told why and can upload again. KYC must also be verified before any payout. If you're asked for documents, please provide them within **{{c:kyc_deadline_days}} days**.$q$,array[$q$Is my ID safe?$q$,$q$How do payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$restricted-countries$q$,$q$getting-started$q$,$q$Which countries are restricted? Can I use a VPN?$q$,array[$q$restricted$q$,$q$which countries$q$,$q$country$q$,$q$available in my country$q$,$q$usa$q$,$q$united states$q$,$q$us residents$q$,$q$canada$q$,$q$ontario$q$,$q$sanctioned$q$,$q$ofac$q$,$q$vpn$q$,$q$proxy$q$,$q$my location$q$,$q$eligible countries$q$,$q$residents$q$,$q$can americans join$q$,$q$americans$q$,$q$american$q$,$q$can i join from$q$,$q$can i use a vpn$q$,$q$can uk residents join$q$,$q$my country$q$,$q$us traders$q$,$q$can i join from the us$q$]::text[],$q$IPFX isn't available where our services are prohibited by law. Residents of **Canada (Ontario)** and any **OFAC-sanctioned country** are not eligible, and we can restrict other jurisdictions at any time. You're responsible for making sure using IPFX is lawful where you live.

Using a **VPN or proxy** to hide your location or get around a restriction is prohibited and can lead to account termination without refund. If you're unsure about your country, ask {{c:contact_email}} before applying.$q$,array[$q$What do I need to apply?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$age-limit$q$,$q$getting-started$q$,$q$How old do I have to be?$q$,array[$q$age$q$,$q$how old$q$,$q$18$q$,$q$under 18$q$,$q$minimum age$q$,$q$over 18$q$,$q$teenager$q$,$q$underage$q$,$q$year old$q$,$q$17 year old$q$,$q$16 year old$q$,$q$teen$q$,$q$can a minor join$q$,$q$under 18s$q$]::text[],$q$You must be **18 or over** to register or start a challenge. We can request age verification at any time and will close accounts belonging to anyone under 18.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$email-verification$q$,$q$getting-started$q$,$q$I didn't get my verification email$q$,array[$q$verification email$q$,$q$confirm email$q$,$q$email not received$q$,$q$didn't get email$q$,$q$no email$q$,$q$confirmation link$q$,$q$verify my email$q$,$q$resend email$q$,$q$spam folder$q$,$q$email confirmed$q$]::text[],$q$Check your spam/junk folder first and search for "IPFX". The confirmation link takes you to a confirmation page on ipfxcapital.com. You need a verified email before you can apply for a challenge. If nothing arrives after a few minutes, check the address you signed up with for typos, or email {{c:contact_email}}.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$forgot-password$q$,$q$getting-started$q$,$q$I forgot my password$q$,array[$q$forgot password$q$,$q$reset password$q$,$q$can't log in$q$,$q$cant login$q$,$q$login problem$q$,$q$password reset$q$,$q$locked out$q$,$q$change password$q$,$q$lost password$q$,$q$cannot sign in$q$,$q$log in$q$]::text[],$q$On the [login page](/login.html) click **"Forgot password?"**, enter your email and we'll send a reset link. Open it on the same device, choose a new password (at least 8 characters) and log in again. Reset links expire — if yours has, request a new one. IPFX will never ask you for your password, so don't share it with anyone (including me).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$change-details-close-account$q$,$q$getting-started$q$,$q$How do I change my details or close my account?$q$,array[$q$change email$q$,$q$change my details$q$,$q$update details$q$,$q$close my account$q$,$q$delete my account$q$,$q$delete account$q$,$q$deactivate$q$,$q$change name$q$,$q$update address$q$,$q$unsubscribe$q$,$q$how do i close my account$q$,$q$close account$q$,$q$close my ipfx account$q$]::text[],$q$Email {{c:contact_email}} from your registered address to change your details or close your account. Closing an account doesn't refund a challenge fee for a challenge that was already activated. To delete your personal data see "What are my data rights?".$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$multiple-accounts$q$,$q$getting-started$q$,$q$Can I have more than one account or challenge?$q$,array[$q$multiple accounts$q$,$q$more than one account$q$,$q$two accounts$q$,$q$second account$q$,$q$several challenges$q$,$q$how many accounts$q$,$q$multi account$q$,$q$another account$q$,$q$different email$q$,$q$two challenges$q$,$q$at the same time$q$,$q$two challenges at the same time$q$,$q$more than one challenge$q$,$q$multiple challenges$q$,$q$run two challenges$q$]::text[],$q$You may hold **one registered user account** only — creating several to get around the rules or promotions leads to termination of all of them. Under that one account you can hold more than one challenge account, subject to our approval. Running the same strategy on several accounts and only claiming the winners, or hedging between accounts, is prohibited. The free Infinity Challenge allows one active account at a time.$q$,array[$q$What trading practices are prohibited?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-overview$q$,$q$infinity$q$,$q$Tell me about the Infinity Challenge$q$,array[$q$infinity$q$,$q$infinity challenge$q$,$q$free challenge$q$,$q$4 stages$q$,$q$four stages$q$,$q$stages$q$,$q$free account$q$,$q$start free$q$,$q$1000 account$q$,$q$$1000$q$,$q$$1k$q$,$q$infinity rules$q$,$q$how does the infinity challenge work$q$,$q$how does infinity work$q$,$q$infinity explained$q$,$q$how many stages$q$,$q$how many stages are there$q$,$q$number of stages$q$]::text[],$q$The **[Infinity Challenge](/infinity.html)** is our free four-stage pathway. You start with a $1,000 simulated account and progress if you meet the rules at each stage:

{{rules:infinity}}

Stage 1 is free with up to 3 attempts per calendar month. Stages 2 and 3 are simulated funded accounts with an {{p:infinity_s2.split_pct}} profit split, and Stage 4 is a professional account on real markets. Like every challenge it needs an approved application.$q$,array[$q$Is Infinity really free?$q$,$q$What happens if I fail a stage?$q$,$q$How do Infinity payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-free$q$,$q$infinity$q$,$q$Is the Infinity Challenge really free?$q$,array[$q$really free$q$,$q$is infinity free$q$,$q$free to start$q$,$q$no fee$q$,$q$no cost$q$,$q$hidden fees$q$,$q$credit card$q$,$q$no credit card$q$,$q$zero cost$q$,$q$cost of infinity$q$,$q$free challenge catch$q$,$q$is there a fee for the free challenge$q$]::text[],$q$Yes — there's **no fee and no credit card** for the Infinity Challenge. You still need to be approved: verify your email, submit an application with ID and proof of address, and our team reviews it ({{c:review_time}}). Stage 1 allows up to {{p:infinity_s1.attempts}} attempts per calendar month at no cost.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-stage1$q$,$q$infinity$q$,$q$Infinity Stage 1 rules$q$,array[$q$stage 1$q$,$q$stage one$q$,$q$infinity stage 1$q$,$q$first stage$q$,$q$prove it$q$,$q$$1000 stage$q$,$q$stage 1 rules$q$,$q$evaluation stage$q$]::text[],$q$**Stage 1 — {{p:infinity_s1.balance}} account (free):**
- Profit target {{p:infinity_s1.target_pct}} ({{p:infinity_s1.target_amt}})
- Max daily loss {{p:infinity_s1.daily_pct}} ({{p:infinity_s1.daily_amt}}); max drawdown {{p:infinity_s1.dd_pct}} ({{p:infinity_s1.dd_amt}}), {{p:infinity_s1.dd_mode}}
- Minimum {{p:infinity_s1.min_days}} trading days and {{p:infinity_s1.min_trades}} trades
- Max risk per trade {{p:infinity_s1.risk_pct}} ({{p:infinity_s1.risk_amt}}), stop-loss required
- Daily profit cap {{p:infinity_s1.cap_pct}} — profit above the cap on one day doesn't count
- Up to {{p:infinity_s1.attempts}} attempts per calendar month$q$,array[$q$Why is there a daily profit cap?$q$,$q$What happens if I fail?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-stage2$q$,$q$infinity$q$,$q$Infinity Stage 2 rules$q$,array[$q$stage 2$q$,$q$stage two$q$,$q$infinity stage 2$q$,$q$second stage$q$,$q$get funded stage$q$,$q$$5000 stage$q$,$q$funded simulation$q$,$q$stage 2 rules$q$]::text[],$q$**Stage 2 — {{p:infinity_s2.balance}} simulated funded account:**
- Profit target {{p:infinity_s2.target_pct}} ({{p:infinity_s2.target_amt}}); profit split {{p:infinity_s2.split_pct}}
- Max daily loss {{p:infinity_s2.daily_pct}}; max drawdown {{p:infinity_s2.dd_pct}} ({{p:infinity_s2.dd_mode}})
- Minimum {{p:infinity_s2.min_days}} trading days and {{p:infinity_s2.min_trades}} trades
- At least {{p:infinity_s2.prof_days_pct}} of trading days must be profitable
- Max risk per trade {{p:infinity_s2.risk_pct}}, stop-loss required

Your Stage 2 earnings are **held** and released when you reach the 3% milestone in Stage 3 (see "How do Infinity payouts work?").$q$,array[$q$How do Infinity payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-stage3$q$,$q$infinity$q$,$q$Infinity Stage 3 rules$q$,array[$q$stage 3$q$,$q$stage three$q$,$q$infinity stage 3$q$,$q$third stage$q$,$q$qualification$q$,$q$$10000 stage$q$,$q$stage 3 rules$q$,$q$qualify$q$]::text[],$q$**Stage 3 — {{p:infinity_s3.balance}} account (qualification):**
- Profit target {{p:infinity_s3.target_pct}} ({{p:infinity_s3.target_amt}}); profit split {{p:infinity_s3.split_pct}}
- Max daily loss {{p:infinity_s3.daily_pct}}; max drawdown {{p:infinity_s3.dd_pct}} ({{p:infinity_s3.dd_mode}})
- Minimum {{p:infinity_s3.min_days}} trading days and {{p:infinity_s3.min_trades}} trades
- Max risk per trade {{p:infinity_s3.risk_pct}}, stop-loss required

At 3% profit your held Stage 2 earnings are released; completing the target earns a second payout and triggers our quant review (within 24 hours) before Stage 4.$q$,array[$q$What is the quant review?$q$,$q$How do Infinity payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-stage4$q$,$q$infinity$q$,$q$Infinity Stage 4 (professional account)$q$,array[$q$stage 4$q$,$q$stage four$q$,$q$infinity stage 4$q$,$q$professional$q$,$q$a-book$q$,$q$real markets$q$,$q$stage 4 capital$q$,$q$how much capital stage 4$q$,$q$500k$q$,$q$scale to 500k$q$,$q$capital allocation$q$,$q$scaling$q$,$q$scale up$q$,$q$capital increase$q$,$q$grow my account$q$]::text[],$q$**Stage 4 — professional account on real markets (A-book)** starts at **{{p:infinity_s4.balance}}** with an {{p:infinity_s4.split_pct}} profit split, paid bi-weekly. Any increase in capital is decided by our analysts from your results (Sharpe ratio, drawdown behaviour, risk-to-reward) — there's no automatic entitlement to a larger allocation. Your Stage 3 drawdown, daily loss and sizing limits continue to apply, and the firm can add further risk controls.$q$,array[$q$What is the quant review?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-fail-restart$q$,$q$infinity$q$,$q$What happens if I fail an Infinity stage? How many attempts do I get?$q$,array[$q$fail infinity$q$,$q$fail a stage$q$,$q$breach infinity$q$,$q$restart infinity$q$,$q$attempts$q$,$q$3 attempts$q$,$q$three attempts$q$,$q$retry stage 1$q$,$q$how many attempts$q$,$q$try again infinity$q$,$q$failed stage$q$,$q$start again$q$,$q$monthly attempts$q$,$q$reset infinity$q$]::text[],$q$- **Stage 1:** if you breach a rule your account closes and you can start Stage 1 again — up to **{{p:infinity_s1.attempts}} attempts per calendar month**, free. A further attempt is available from the 1st of the next month.
- **Stage 2, 3 or 4:** breaching a rule resets you to a fresh Stage 1. Any held Stage 2 earnings that hadn't yet been released are forfeited.
- There's no payment or compensation for failing a stage.

You can only restart when you have no other active account.$q$,array[$q$How do Infinity payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-payouts$q$,$q$infinity$q$,$q$How do Infinity payouts work?$q$,array[$q$infinity payout$q$,$q$infinity payouts$q$,$q$when do i get paid infinity$q$,$q$first payout infinity$q$,$q$stage 2 earnings$q$,$q$held earnings$q$,$q$payout locked$q$,$q$3% milestone$q$,$q$two payouts$q$,$q$bi-weekly$q$,$q$biweekly$q$]::text[],$q$- **Stage 2 earnings are held**, not paid when you finish Stage 2.
- In **Stage 3**, the moment your closed profit reaches **3%**, your Stage 2 earnings (your {{p:infinity_s2.split_pct}} share) are released as your first payout.
- Completing Stage 3 earns a **second payout** — {{p:infinity_s3.split_pct}} of your Stage 3 profit.
- After the quant review you move to Stage 4 with **bi-weekly** payouts.
- If you fail in Stage 2, 3 or 4 before the milestone, held earnings are forfeited.

Payouts also require verified KYC and are reviewed by our team.$q$,array[$q$What is the quant review?$q$,$q$What ID do you accept?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$infinity-profit-cap$q$,$q$infinity$q$,$q$Why is there a daily profit cap in Stage 1?$q$,array[$q$daily profit cap$q$,$q$profit cap$q$,$q$cap on profit$q$,$q$cant make more than$q$,$q$max profit per day$q$,$q$3% cap$q$,$q$profit limit per day$q$,$q$capped profit$q$]::text[],$q$Stage 1 counts at most **{{p:infinity_s1.cap_pct}} profit per day** ({{p:infinity_s1.target_amt}} target overall). It exists so a single lucky trade or day can't pass the stage — the result has to be repeatable across days. Profit above the cap on a day doesn't count towards the target. Losses always count in full.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$quant-review$q$,$q$infinity$q$,$q$What is the quant review?$q$,array[$q$quant review$q$,$q$quantitative review$q$,$q$analyst review$q$,$q$sharpe$q$,$q$stage 3 review$q$,$q$review of my trades$q$,$q$why review$q$,$q$quant team$q$]::text[],$q$When you complete Stage 3 our quantitative team reviews your trading across Stages 1–3 — Sharpe ratio, drawdown behaviour, average risk-to-reward, position sizing consistency, session and instrument concentration, and whether results look like genuine edge or noise. It's completed **within 24 hours** and you're notified of the outcome. We can decline Stage 4 for traders who hit the numbers but whose pattern doesn't reflect systematic, repeatable skill.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$traditional-overview$q$,$q$traditional$q$,$q$Tell me about the Traditional Challenge$q$,array[$q$traditional$q$,$q$traditional challenge$q$,$q$paid challenge$q$,$q$3 phase$q$,$q$three phase$q$,$q$phases$q$,$q$standard challenge$q$,$q$forex challenge$q$,$q$traditional rules$q$,$q$phase 1$q$,$q$phase 2$q$,$q$phase 3$q$,$q$how many phases$q$]::text[],$q$The **Traditional Challenge** is a paid evaluation on a simulated account of $10K–$200K.

{{rules:traditional}}

**Fees (Phase 1):** {{fees:traditional}}. Phases 2 and 3 are free. Pass all the phases and your funded account opens automatically. Your fee is credited back with your first eligible payout (see "Is the fee refundable?"). You need an approved application before paying.$q$,array[$q$Is the fee refundable?$q$,$q$What if I fail a phase?$q$,$q$What is the stop-loss rule?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$traditional-fees$q$,$q$traditional$q$,$q$How much does the Traditional Challenge cost?$q$,array[$q$traditional fee$q$,$q$how much is traditional$q$,$q$traditional price$q$,$q$cost of challenge$q$,$q$price of 50k$q$,$q$price list$q$,$q$challenge prices$q$]::text[],$q$Traditional Challenge fees (one-off, USD): **{{fees:traditional}}**. See also the Futures ({{fees:futures}}) and PAC ({{fees:pac}}) fees. The Infinity Challenge is free. Tell me the size you're considering (e.g. "$50K") and I'll show the fee and limits.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$traditional-fail$q$,$q$traditional$q$,$q$What if I fail a Traditional phase?$q$,array[$q$fail traditional$q$,$q$breach traditional$q$,$q$failed a phase$q$,$q$lost my challenge$q$,$q$phase failure$q$,$q$failed challenge$q$,$q$what happens if i fail$q$,$q$what if i breach$q$,$q$account closed$q$,$q$breached$q$,$q$what happens if i fail the challenge$q$,$q$fail the challenge$q$,$q$failed the challenge$q$]::text[],$q$Breaching any rule (daily loss, max drawdown, a prohibited practice) closes that phase immediately and you don't advance. The fee for the failed phase is **not refunded**, and there's no automatic restart — you'd purchase a new challenge (subject to approval). Where a reset is offered it's a separate paid service. Rules for breaches are the same on every programme: see "What happens if I breach a rule?".$q$,array[$q$Is the fee refundable?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$stop-loss-risk-rule$q$,$q$traditional$q$,$q$What is the stop-loss and risk-per-trade rule?$q$,array[$q$stop loss required$q$,$q$mandatory stop loss$q$,$q$must use stop loss$q$,$q$risk per trade$q$,$q$max risk per trade$q$,$q$1% risk$q$,$q$position size limit$q$,$q$risk rule$q$,$q$no stop loss$q$,$q$trade without stop loss$q$,$q$stop loss rule$q$,$q$stop loss compulsory$q$,$q$is stop loss compulsory$q$,$q$compulsory$q$]::text[],$q$Some programmes require a stop-loss on every order and cap the risk per trade (measured from entry to stop as a % of your starting balance):

{{cmp:risk}}

An order that breaks these rules is rejected. Stops aren't guaranteed — in a gap the position closes at the next available price. See "What are the execution costs?" for slippage.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$futures-overview$q$,$q$futures$q$,$q$Tell me about the Futures Challenge$q$,array[$q$futures$q$,$q$futures challenge$q$,$q$cme$q$,$q$cme futures$q$,$q$futures rules$q$,$q$eod drawdown$q$,$q$trailing drawdown futures$q$,$q$micro contracts$q$,$q$es nq$q$,$q$futures trading$q$,$q$futures account$q$]::text[],$q$The **[Futures Challenge](/futures.html)** is a paid two-phase evaluation ($25K–$150K) with an **end-of-day trailing drawdown**:

{{rules:futures}}

**Fees (Phase 1):** {{fees:futures}}. There's no consistency rule to pass the evaluation, and payouts have standard consistency checks.

Futures accounts trade CME futures only, in whole contracts, and must be flat by 16:00 CT each trading day (no weekend positions).$q$,array[$q$Which instruments can I trade?$q$,$q$Is the fee refundable?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$futures-markets$q$,$q$futures$q$,$q$Can I trade CME futures (ES, NQ, CL, GC)?$q$,array[$q$can i trade es$q$,$q$nq$q$,$q$es futures$q$,$q$cme contracts$q$,$q$e-mini$q$,$q$mes mnq$q$,$q$crude oil futures$q$,$q$gold futures$q$,$q$futures markets available$q$,$q$which futures$q$,$q$futures instruments$q$,$q$micro contracts available$q$,$q$can i trade micro contracts$q$,$q$micro contracts$q$,$q$micro futures$q$,$q$trade the s&p futures$q$,$q$s&p futures$q$,$q$nasdaq futures$q$]::text[],$q$The [Futures Challenge page](/futures.html) lists CME markets such as ES/MES, NQ/MNQ, YM/MYM, CL/MCL and GC/MGC. The instruments currently **enabled in IPFX Markets** are:

{{instruments}}

{{futures_status}} Futures instruments trade only on Futures Challenge accounts (and Futures accounts trade futures only), in whole contracts. The 30-year and 10-year Treasuries (ZB, ZN) need a $100K or larger account. Prices come from a free data feed that is for simulated evaluation only.$q$,array[$q$Which instruments can I trade?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$pac-overview$q$,$q$pac$q$,$q$What is the Personalised Application Challenge (PAC)?$q$,array[$q$pac$q$,$q$personalised challenge$q$,$q$personalized challenge$q$,$q$application challenge$q$,$q$what is the pac$q$,$q$custom challenge$q$,$q$bespoke$q$,$q$no evaluation$q$,$q$funded from day one$q$,$q$strategy disclosure$q$,$q$already profitable$q$,$q$negotiated$q$,$q$how does the application challenge work$q$,$q$how does the pac work$q$]::text[],$q$The **[PAC](/personalised-challenge.html)** is for traders who already have a documented, profitable strategy. There's no standard evaluation phase:
1. **Apply and disclose** your strategy in full (entries/exits, instruments, sizing, track record).
2. Our analysts **backtest it** and agree custom parameters with you in writing.
3. Once agreed, your funded account goes live.

{{rules:pac}}

**Entry fees:** {{fees:pac}}. Applications are reviewed in {{c:pac_review_time}}; we can accept, reject or modify an application, and parameters are set by a separate written agreement.$q$,array[$q$What do I need for the PAC?$q$,$q$Is the PAC fee refundable?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$pac-requirements$q$,$q$pac$q$,$q$What do I need to apply for the PAC?$q$,array[$q$pac requirements$q$,$q$pac track record$q$,$q$what do i need for pac$q$,$q$track record$q$,$q$backtest$q$,$q$myfxbook$q$,$q$strategy details$q$,$q$pac apply$q$,$q$evidence$q$,$q$risk management evidence$q$,$q$what do i need for the pac$q$,$q$requirements for the pac$q$]::text[],$q$For the PAC you need:
- a **full strategy disclosure** — entry/exit rules, indicators, timeframes, instruments, position sizing and risk management
- a **verified track record** of at least 3 months (live or demo — Myfxbook, FX Blue, broker statements or EA logs)
- evidence of consistent sizing, defined stop-loss use and controlled drawdown
- the standard ID and proof-of-address checks

Strategies with no defined risk framework won't be approved. Your strategy data is treated as confidential.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$pac-scaling-refund$q$,$q$pac$q$,$q$Can I scale a PAC account? Is the PAC fee refundable?$q$,array[$q$pac scaling$q$,$q$scale pac$q$,$q$pac fee refund$q$,$q$pac refundable$q$,$q$capital increase pac$q$,$q$500k pac$q$,$q$increase capital$q$,$q$after 3 months$q$]::text[],$q$- **Scaling:** after about 3 months of consistent, disciplined trading you can apply for a capital increase (up to $500K, no extra fee) — it's at IPFX's discretion, not guaranteed.
- **Fee:** the PAC entry fee is one-off and is credited against your first eligible payout once the payout conditions are met (see "Is the fee refundable?").$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$daily-loss-limit$q$,$q$rules$q$,$q$What is the daily loss limit?$q$,array[$q$daily loss$q$,$q$daily loss limit$q$,$q$max daily loss$q$,$q$daily drawdown$q$,$q$daily limit$q$,$q$loss per day$q$,$q$daily stop$q$,$q$daily reset$q$,$q$what time does daily reset$q$,$q$how does daily drawdown work$q$,$q$how much can i lose in a day$q$,$q$maximum loss per day$q$,$q$max loss per day$q$,$q$max loss allowed per day$q$]::text[],$q$The **daily loss limit** is the most your equity can fall within a single trading day. Breaching it at any moment closes the account, whatever your overall result.

{{cmp:daily}}

For accounts opened on or after {{c:rules_v2_date}}, each day's starting level is the **higher of balance and equity at 00:00 UTC**, so a floating loss carried past midnight counts towards the new day's limit.$q$,array[$q$What is the max drawdown?$q$,$q$What happens if I breach a rule?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$max-drawdown$q$,$q$rules$q$,$q$What is max drawdown (static vs trailing)?$q$,array[$q$drawdown$q$,$q$max drawdown$q$,$q$trailing drawdown$q$,$q$static drawdown$q$,$q$eod drawdown$q$,$q$overall loss$q$,$q$max overall loss$q$,$q$total loss limit$q$,$q$how is drawdown calculated$q$,$q$drawdown explained$q$,$q$what is drawdown$q$,$q$equity peak$q$,$q$how much can i lose$q$,$q$how much can i lose before i fail$q$,$q$how much can i lose overall$q$,$q$maximum loss$q$]::text[],$q$**Max drawdown** is the largest fall in equity allowed overall. There are three kinds:
- **Static** — measured from your *starting balance* and never moves (Traditional, PAC default).
- **Trailing** — measured from your *highest equity ever*, so it rises as you profit (Infinity Stages 1–3).
- **End-of-day trailing** — trails your highest *end-of-day* balance; intraday swings don't move it (Futures, Infinity Stage 4).

Current limits:
{{cmp:drawdown}}

Reaching the limit closes the account.$q$,array[$q$What is the daily loss limit?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$profit-target$q$,$q$rules$q$,$q$What are the profit targets?$q$,array[$q$profit target$q$,$q$targets$q$,$q$how much profit do i need$q$,$q$target percentage$q$,$q$phase target$q$,$q$how much to pass$q$,$q$pass target$q$,$q$profit goal$q$,$q$8%$q$,$q$closed trades$q$]::text[],$q${{cmp:target}}

Profit counts on **closed trades only** — floating profit doesn't count. Reaching the target isn't enough on its own: you must also meet the minimum trading days and trades (and, in Infinity Stage 2, the profitable-days requirement).$q$,array[$q$What are the minimum trading days?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$minimum-days-trades$q$,$q$rules$q$,$q$What are the minimum trading days and trades?$q$,array[$q$minimum trading days$q$,$q$min days$q$,$q$minimum days$q$,$q$how many days$q$,$q$minimum trades$q$,$q$how many trades$q$,$q$trading day definition$q$,$q$what counts as a trading day$q$,$q$60 seconds$q$,$q$holding time$q$,$q$profitable day$q$]::text[],$q$**Minimum trading days:**
{{cmp:min_days}}

**Minimum trades:**
{{cmp:min_trades}}

A trading day is a calendar day on which at least one trade was opened **and** closed. For accounts opened on or after {{c:rules_v2_date}}, a trade only counts if it was held at least **60 seconds**, partial closes don't create extra counted trades, and a day counts as profitable only if it closes at least 0.25% of the starting balance in profit.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$consistency-rules$q$,$q$rules$q$,$q$Is there a consistency rule?$q$,array[$q$consistency$q$,$q$consistency rule$q$,$q$no consistency rule$q$,$q$one big day$q$,$q$single day profit$q$,$q$best day rule$q$,$q$40% rule$q$,$q$25% rule$q$,$q$single trade profit$q$]::text[],$q$- **To pass the evaluation:** Traditional and Futures have **no consistency rule**. Infinity Stage 1 has a daily profit cap and Stage 2 requires a share of profitable days.
- **To be paid:** payouts have consistency checks — no single trade may be more than **25%** of the period's profit; for accounts opened on or after {{c:rules_v2_date}}, the period must also include at least **4 trading days** and no single day may exceed **40%** of the profit.$q$,array[$q$How do payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$breach-what-happens$q$,$q$rules$q$,$q$What happens if I breach a rule?$q$,array[$q$breach$q$,$q$breached$q$,$q$rule breach$q$,$q$what if i break a rule$q$,$q$account closed$q$,$q$blown$q$,$q$blow up$q$,$q$hit the limit$q$,$q$hit drawdown$q$,$q$failed$q$,$q$violated$q$,$q$what does breach mean$q$,$q$i blew my account$q$,$q$blew my account$q$,$q$blown account$q$,$q$account blown$q$,$q$what now$q$]::text[],$q$Breaching a trading parameter (daily loss, max drawdown, prohibited practice) closes the account **immediately**, fees aren't refunded and any pending profit split is forfeited. On the Infinity Challenge you can restart Stage 1 (up to {{p:infinity_s1.attempts}} times a month); on paid programmes you'd buy a new challenge.

I can't see individual accounts — for a specific breach, email {{c:contact_email}} with your registered email.$q$,array[$q$What are the execution costs?$q$,$q$Is the fee refundable?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$prohibited-practices$q$,$q$rules$q$,$q$What trading practices are prohibited?$q$,array[$q$prohibited$q$,$q$not allowed$q$,$q$banned strategies$q$,$q$cheating$q$,$q$rules of trading$q$,$q$what can't i do$q$,$q$forbidden$q$,$q$allowed strategies$q$,$q$what is allowed$q$,$q$terms of trading$q$]::text[],$q$The main prohibited practices (Terms section 8) are:
- **Arbitrage and latency exploitation** — tick scalping, exploiting price delays or feed differences
- **Hedging or coordinating across accounts** (yours or anyone else's)
- **Copy trading and signals** — copying, being copied, or letting anyone else trade your account
- **Unapproved bots/EAs** — algorithms need written approval first
- **Martingale, grid and aggressive averaging** (unless agreed for a PAC)
- **Single-trade gambling** or reverse-engineering the exact targets
- **Exploiting platform errors** (report them instead) and **VPN/location masking**
- **Account sharing** and multiple registered accounts

Breaches mean immediate closure with no refund. Read section 8 of the [Terms](/terms.html) for the full wording.$q$,array[$q$Can I use an EA or bot?$q$,$q$Is scalping allowed?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$scalping-latency$q$,$q$rules$q$,$q$Is scalping allowed?$q$,array[$q$scalping$q$,$q$scalp$q$,$q$scalper$q$,$q$high frequency$q$,$q$hft$q$,$q$tick scalping$q$,$q$latency arbitrage$q$,$q$quick trades$q$,$q$fast trades$q$,$q$short trades$q$,$q$minimum holding$q$,$q$arbitrage$q$,$q$order rate$q$,$q$too many orders$q$,$q$max number of trades$q$,$q$max trades per day$q$,$q$trade limit$q$,$q$how many trades can i place$q$,$q$is there a max number of trades per day$q$]::text[],$q$Scalping as a style is fine, but **tick scalping and latency/arbitrage exploitation are prohibited**. For accounts opened on or after {{c:rules_v2_date}}:
- **Profit from a trade closed less than 60 seconds after opening doesn't count** towards your target (losses still count in full).
- No more than **5 new orders in any 10 seconds** — extra orders are rejected.
- Market orders have a short execution delay and slippage (see "What are the execution costs?").$q$,array[$q$What are the execution costs?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$ea-bots$q$,$q$rules$q$,$q$Can I use an EA or trading bot?$q$,array[$q$ea$q$,$q$expert advisor$q$,$q$trading bot$q$,$q$algo trading$q$,$q$automated trading$q$,$q$can i use a bot$q$,$q$algorithm$q$,$q$api trading$q$,$q$automation$q$,$q$mt4 ea$q$,$q$python bot$q$,$q$robot$q$,$q$can i use an ea$q$,$q$are bots allowed$q$,$q$run my bot$q$,$q$can i run a bot$q$,$q$run an ea$q$,$q$use my ea$q$,$q$can i run my bot on your platform$q$]::text[],$q$Only through IPFX Markets, and only with written approval. Third-party software, EAs and any programmatic connection are prohibited unless you've submitted the full strategy (code, language, max risk per trade) via the designated tool and IPFX has **explicitly approved it in writing** — submission alone isn't approval. You stay responsible for everything the algorithm does. Personalised Application Challenge traders can agree algorithmic trading as part of their application.$q$,array[$q$What is the PAC?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$copy-trading$q$,$q$rules$q$,$q$Is copy trading allowed?$q$,array[$q$copy trading$q$,$q$copytrade$q$,$q$signals$q$,$q$signal provider$q$,$q$telegram signals$q$,$q$trade copier$q$,$q$mirror trades$q$,$q$follow another trader$q$,$q$master follower$q$,$q$challenge passing service$q$,$q$pass my challenge for me$q$,$q$managed account$q$,$q$someone else trade my account$q$,$q$let someone trade my account$q$,$q$share my account$q$,$q$friend trade my account$q$,$q$give my login to someone$q$,$q$someone trade for me$q$,$q$trade together$q$,$q$friend and i$q$,$q$trade with a friend$q$,$q$joint account$q$,$q$shared account$q$,$q$i use a trade copier$q$,$q$signal group$q$,$q$trade with a signal group$q$]::text[],$q$No. Copy trading is **prohibited on every evaluation and funded account**, whether you're the follower or the source. It also covers acting on signals from Telegram/Discord/social accounts, using a "challenge passing" or account-management service, and having anyone direct your trades in real time. Every trade must be your own independent decision. Breaches lead to termination of all involved accounts with no refund or payout.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$news-weekend-hold$q$,$q$rules$q$,$q$Can I trade news or hold trades over weekends?$q$,array[$q$news trading$q$,$q$news$q$,$q$economic calendar$q$,$q$high impact news$q$,$q$weekend$q$,$q$overnight$q$,$q$hold over weekend$q$,$q$swing$q$,$q$hold trades overnight$q$,$q$gap risk$q$,$q$nfp$q$,$q$fomc$q$]::text[],$q$Unless your programme says otherwise you can hold positions overnight and over weekends (except on Futures accounts, which must be flat by 16:00 CT each trading day and over weekends) (you carry the gap risk), and news trading is allowed. Where a programme specifies news windows, trades opened inside them may be cancelled and won't count. IPFX may restrict overnight or weekend holding in specific market conditions with reasonable notice. Also remember the daily loss limit includes floating losses carried past midnight.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$leverage-margin$q$,$q$trading$q$,$q$What leverage do you offer?$q$,array[$q$leverage$q$,$q$margin$q$,$q$1:100$q$,$q$what leverage$q$,$q$max leverage$q$,$q$margin call$q$,$q$lot size$q$,$q$position size limits$q$]::text[],$q$IPFX Markets uses **{{c:leverage}} leverage**. Position size is also limited by the per-trade risk rules on your programme and by maximum lot sizes. For accounts opened on or after {{c:rules_v2_date}} on programmes with a per-trade risk cap, the combined risk of all open positions (entry to stop-loss) may not exceed **three times** that cap.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$instruments$q$,$q$trading$q$,$q$Which instruments can I trade?$q$,array[$q$instruments$q$,$q$what can i trade$q$,$q$which pairs$q$,$q$markets available$q$,$q$forex pairs$q$,$q$symbols$q$,$q$indices$q$,$q$metals$q$,$q$crypto$q$,$q$commodities$q$,$q$stocks$q$,$q$shares$q$,$q$oil$q$,$q$tradable$q$,$q$trading pairs$q$,$q$what markets can i trade$q$,$q$which markets can i trade$q$]::text[],$q$The instruments currently enabled in IPFX Markets:

{{instruments}}

{{futures_status}} Which instruments your account can trade depends on your programme, and the list can change — IPFX Markets always shows what's available.$q$,array[$q$Can I trade CME futures?$q$,$q$What leverage do you offer?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$execution-costs$q$,$q$trading$q$,$q$What are the execution costs (slippage, commission, delay)?$q$,array[$q$slippage$q$,$q$commission$q$,$q$spread$q$,$q$execution delay$q$,$q$fees per trade$q$,$q$trading costs$q$,$q$execution costs$q$,$q$fill price$q$,$q$delay$q$,$q$requote$q$,$q$how are orders filled$q$,$q$stop not guaranteed$q$,$q$gap$q$]::text[],$q$The platform is a simulation designed to behave like real markets. For evaluation accounts opened on or after **{{c:rules_v2_date}}** (and funded accounts arising from them):
- **Execution delay:** market orders and closes you initiate execute after up to one second, at the less favourable of the price when received and when executed.
- **Slippage:** applies to market orders, closes, stop-loss fills and triggered stops — currently up to about 0.3 basis points on forex, 0.3–0.5 on CME futures, 0.5 on metals/indices and 5 on crypto. Take-profit and limit orders fill at their price or better.
- **Commission:** US$6 per standard lot round-turn on forex and metals; US$4 per full-size and US$1 per micro futures contract round-turn; none on indices and crypto.
- **Stops aren't guaranteed** across gaps, and abnormal off-market prices may be disregarded.

Costs are shown on every trade in your history. Rates can change under the Terms (section 18).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$platform-ipfx-markets$q$,$q$trading$q$,$q$What trading platform do you use? MT4/MT5? Desktop app?$q$,array[$q$platform$q$,$q$ipfx markets$q$,$q$mt4$q$,$q$mt5$q$,$q$metatrader$q$,$q$ctrader$q$,$q$tradingview$q$,$q$desktop app$q$,$q$web platform$q$,$q$which platform$q$,$q$trading platform$q$,$q$app$q$,$q$mobile app$q$,$q$ios$q$,$q$android$q$,$q$charts$q$,$q$download$q$,$q$mac$q$,$q$windows$q$,$q$do you support mt4$q$,$q$mt4 support$q$,$q$do you support metatrader$q$,$q$support mt5$q$,$q$do you support ctrader$q$,$q$do you support tradingview$q$]::text[],$q$All trading happens on **IPFX Markets**, our own web platform (open it from your dashboard). MetaTrader 4/5, cTrader and other third-party platforms aren't supported. {{c:desktop_status}} Charts are built into IPFX Markets; prices are for simulated evaluation and may differ from live exchange prices.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$market-data-prices$q$,$q$trading$q$,$q$Are the prices real? Why are prices different?$q$,array[$q$are prices real$q$,$q$price feed$q$,$q$different prices$q$,$q$price lag$q$,$q$delayed prices$q$,$q$stale price$q$,$q$wrong price$q$,$q$price difference$q$,$q$data feed$q$,$q$tick data$q$,$q$quotes$q$,$q$why is the price different$q$]::text[],$q$IPFX Markets prices are suitable for **simulated evaluation** and are not represented as exchange tick-by-tick data, so they can differ from your broker or exchange. If a price looks wrong, don't trade on it — report it straight away to {{c:contact_email}} (exploiting a known platform error is prohibited and its profits are void). Orders are rejected when no fresh, reliable price is available.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$trading-hours$q$,$q$trading$q$,$q$When can I trade? What are the market hours?$q$,array[$q$trading hours$q$,$q$market hours$q$,$q$when can i trade$q$,$q$open hours$q$,$q$sessions$q$,$q$weekend trading$q$,$q$market closed$q$,$q$24/7$q$,$q$maintenance$q$,$q$downtime$q$]::text[],$q$Each instrument follows its own trading sessions, shown in IPFX Markets — orders are rejected while a market is closed or no reliable price exists. The daily loss limit day runs 00:00–23:59 server time (UTC). Scheduled maintenance or outages can occur; see section 15.2 of the [Terms](/terms.html).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$payout-how$q$,$q$payouts$q$,$q$How do payouts work? How do I withdraw?$q$,array[$q$payout$q$,$q$payouts$q$,$q$how do i get paid$q$,$q$withdraw$q$,$q$withdrawal$q$,$q$request payout$q$,$q$cash out$q$,$q$get my money$q$,$q$payout process$q$,$q$how to withdraw$q$,$q$profit split payout$q$,$q$payout schedule$q$,$q$payout frequency$q$,$q$how often$q$,$q$minimum payout$q$,$q$weekly payout$q$,$q$biweekly payout$q$,$q$keep the profits$q$,$q$keep my profits$q$,$q$do i keep my profits$q$,$q$do i keep 100%$q$,$q$how long till i get my money$q$,$q$how long do payouts take$q$,$q$how long does a payout take$q$,$q$when will i receive my payout$q$,$q$do you pay on time$q$,$q$are payouts on time$q$,$q$how much can i withdraw$q$,$q$what is the split$q$,$q$do i get paid straight away$q$,$q$instant payout$q$,$q$how quickly do i get paid$q$,$q$when can i request my first payout$q$,$q$when is the earliest i can request$q$]::text[],$q$You request payouts from the **Payouts** page of your dashboard once you have a funded account in good standing. To be eligible:
- your **identity (KYC) is verified**
- at least **{{c:payout_min_days}} days** since your last payout (or since the account was funded)
- the payout is at least **${{c:payout_min_usd}}**
- you pass the **consistency checks** (see "Is there a consistency rule?")
- no investigation or hold is open on the account

Every request is **reviewed by our team**; once approved it's typically processed in **{{c:payout_processing}}**. Payments go only to your own verified payout method. Your share is **{{p:trad_25k_p1.split_pct}}** of net profit. The very first payout has an extra profit threshold — see "What's needed for my first payout?".$q$,array[$q$What's needed for my first payout?$q$,$q$Why was my payout withheld?$q$,$q$Is the fee refundable?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$payout-first$q$,$q$payouts$q$,$q$What's needed for my first payout?$q$,array[$q$first payout$q$,$q$first withdrawal$q$,$q$5% threshold$q$,$q$minimum profit first payout$q$,$q$first payout requirement$q$,$q$when can i withdraw first$q$,$q$fee credit$q$,$q$when can i request my first payout$q$,$q$earliest first payout$q$,$q$when is the earliest i can request my first payout$q$]::text[],$q$Before your **first** payout on a funded account you must reach at least **{{c:first_payout_threshold_pct}}% net realised (closed) profit** on the funded starting balance — e.g. $1,250 on a $25,000 account. Floating profit doesn't count. It's a one-off requirement; later payouts follow the normal conditions.

Once you're eligible, your **challenge fee is added to your first profit-split payment** as a single combined payment (see "Is the fee refundable?").$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$payout-consistency-denied$q$,$q$payouts$q$,$q$Why was my payout denied or withheld?$q$,array[$q$payout denied$q$,$q$payout rejected$q$,$q$payout withheld$q$,$q$payout delayed$q$,$q$payout not received$q$,$q$where is my payout$q$,$q$payout pending$q$,$q$payout failed$q$,$q$not paid$q$,$q$payout problem$q$,$q$payout error$q$,$q$too soon$q$,$q$below minimum$q$,$q$consistency failed$q$]::text[],$q$Common reasons a payout request is refused or held:
- KYC isn't verified yet, or documents haven't been supplied within {{c:kyc_deadline_days}} days of a request
- fewer than {{c:payout_min_days}} days since the last payout, or under the ${{c:payout_min_usd}} minimum
- a consistency check failed (one trade above 25% of the period's profit; and on newer accounts, under 4 trading days or one day above 40%)
- an investigation/hold or unresolved rule breach on the account
- a force-majeure or security suspension

I can't look at your request. Email {{c:contact_email}} from your registered address with the payout date and amount (no documents or card details) and the team will check.$q$,array[$q$How do payouts work?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$payout-methods-tax$q$,$q$payouts$q$,$q$How will I be paid? Do I pay tax?$q$,array[$q$payout methods$q$,$q$payment method$q$,$q$how am i paid$q$,$q$bank transfer$q$,$q$paypal$q$,$q$crypto payout$q$,$q$usdt$q$,$q$tax$q$,$q$taxes$q$,$q$hmrc$q$,$q$income tax$q$,$q$payout currency$q$,$q$third party payment$q$,$q$payout to someone else$q$,$q$how will i be paid$q$,$q$how do you pay me$q$,$q$paid by paypal$q$,$q$paypal payout$q$]::text[],$q$You add a payout method on the **Payouts** page of your dashboard — currently **bank transfer, PayPal or wire**. Payments are made **only to your own verified method**, never to a third party, in USD, and timing can vary with the provider and your bank's country. Store a reference only (never a full card or account number). Methods can change, so email {{c:contact_email}} if you need to confirm one. You're **responsible for any tax** on payouts in your country; IPFX doesn't withhold tax unless the law requires it and can supply payment records on request. We can't give tax advice.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$fee-refundable$q$,$q$fees$q$,$q$Is the challenge fee refundable?$q$,array[$q$refund$q$,$q$refundable$q$,$q$money back$q$,$q$fee back$q$,$q$get my fee back$q$,$q$fee credit$q$,$q$credited$q$,$q$refund policy$q$,$q$can i get a refund$q$,$q$chargeback$q$,$q$cancel$q$,$q$cancellation$q$,$q$14 day$q$,$q$cooling off$q$,$q$cancel my purchase$q$,$q$do i get my fee back$q$,$q$is the fee refundable$q$,$q$what happens to my fee$q$,$q$what happens to my fee if i pass$q$,$q$do i get my fee back if i pass$q$]::text[],$q$- **Not refundable once activated:** once your evaluation account is activated and you've started trading, the fee is non-refundable, and your 14-day cancellation right ends.
- **Cancel before activating:** if you've paid but haven't placed any trade, you can cancel within **14 days** for a full refund — email {{c:contact_email}} *before* you trade.
- **Credited on your first payout:** when you reach your first payout eligibility (see "What's needed for my first payout?"), the fee for that programme is **added to your first profit-split payment**.
- No refund where a rule was broken, and please don't raise a chargeback (except for genuine fraud) — it leads to suspension.

The Infinity Challenge has no fee. See section 6 of the [Terms](/terms.html).$q$,array[$q$What's needed for my first payout?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$payment-methods$q$,$q$fees$q$,$q$How can I pay? Which payment methods do you accept?$q$,array[$q$payment methods$q$,$q$how do i pay$q$,$q$pay with card$q$,$q$credit card$q$,$q$debit card$q$,$q$crypto payment$q$,$q$paypal$q$,$q$apple pay$q$,$q$bank transfer$q$,$q$visa$q$,$q$mastercard$q$,$q$stripe$q$,$q$pay with crypto$q$,$q$usdt$q$,$q$bitcoin payment$q$,$q$checkout$q$]::text[],$q$You pay **after** your application is approved, on the checkout step. Card payments are handled by our payment processor (we never see your full card details) and a crypto option is also available where enabled. {{c:checkout_note}} Fees are in US dollars; you cover any currency-conversion or bank charges, and taxes only where the law requires them.$q$,array[$q$Is the fee refundable?$q$,$q$How much does it cost?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$fees-overview$q$,$q$fees$q$,$q$What are the fees? How much does it cost?$q$,array[$q$fees$q$,$q$how much does it cost$q$,$q$price$q$,$q$prices$q$,$q$pricing$q$,$q$cost$q$,$q$cheapest$q$,$q$affordable$q$,$q$how much is it$q$,$q$fee list$q$,$q$challenge cost$q$,$q$entry fee$q$,$q$what are the fees$q$,$q$what are your fees$q$,$q$how much are the challenges$q$]::text[],$q$- **Infinity:** free
- **Traditional (Phase 1):** {{fees:traditional}}
- **Futures (Phase 1):** {{fees:futures}}
- **PAC (entry):** {{fees:pac}}

Fees are one-off, in USD, with no subscriptions, and are credited back with your first eligible payout. You pay only after your application is approved. Ask about a specific size (e.g. "$50K fee") for the details.$q$,array[$q$Is the fee refundable?$q$,$q$What are the drawdown rules?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$reset-retry$q$,$q$fees$q$,$q$Can I reset or retry a challenge?$q$,array[$q$reset$q$,$q$retry$q$,$q$restart$q$,$q$reset challenge$q$,$q$try again$q$,$q$second chance$q$,$q$buy again$q$,$q$reset fee$q$,$q$discounted retry$q$,$q$re-enter$q$,$q$another attempt$q$,$q$start over$q$,$q$can i retry after failing$q$,$q$retry after failing$q$]::text[],$q$- **Infinity:** free restarts of Stage 1 — up to {{p:infinity_s1.attempts}} attempts per calendar month.
- **Traditional / Futures:** there's no automatic restart. After a failure you'd buy a new challenge (subject to approval); where a reset is offered it's a separate paid service and doesn't refund the original fee.
- A failed challenge isn't a ban — you can apply again.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$promo-discount$q$,$q$fees$q$,$q$Do you have promo codes or discounts?$q$,array[$q$promo code$q$,$q$discount$q$,$q$coupon$q$,$q$voucher$q$,$q$offer$q$,$q$sale$q$,$q$black friday$q$,$q$deal$q$,$q$code$q$,$q$special offer$q$,$q$cheaper$q$,$q$free trial$q$]::text[],$q$Promo codes and offers are issued by IPFX from time to time — I don't have a list of active ones. If you've been given a code, use it as instructed when you received it; otherwise follow our announcements on [Discord]({{c:discord_url}}) or email {{c:contact_email}}. The Infinity Challenge is always free to start.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$referral$q$,$q$referral$q$,$q$How does the referral programme work?$q$,array[$q$referral$q$,$q$refer a friend$q$,$q$affiliate$q$,$q$referral code$q$,$q$referral link$q$,$q$commission$q$,$q$invite$q$,$q$earn by referring$q$,$q$referral reward$q$,$q$how do i refer$q$,$q$affiliate programme$q$,$q$partner$q$]::text[],$q$Share your referral link from your dashboard. When someone you refer buys a challenge, gets funded and receives their **first payout**, you earn **{{c:referral_pct}}% of their challenge fee** as a reward.

Conditions: the friend must be a genuinely new customer using your link or code; self-referrals and rewards where you and the referred trader use the same network aren't paid; there's a default cap of 50 qualifying referrals per year unless the programme page says otherwise; and referrals must not be used for copy trading or signal-selling. Rewards can be withheld or reversed for fraud. See section 21 of the [Terms](/terms.html).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$is-id-safe$q$,$q$privacy$q$,$q$Is my ID and personal data safe?$q$,array[$q$is my id safe$q$,$q$data safe$q$,$q$personal data$q$,$q$privacy$q$,$q$how do you store my id$q$,$q$who sees my documents$q$,$q$data security$q$,$q$encryption$q$,$q$data protection$q$,$q$gdpr$q$,$q$what do you do with my data$q$,$q$do you sell my data$q$,$q$documents secure$q$,$q$who has access$q$,$q$is my id secure$q$,$q$is my passport safe$q$,$q$is my personal info safe$q$,$q$is my personal information safe$q$,$q$how do you protect my personal information$q$,$q$keep my id$q$,$q$keep it forever$q$,$q$store my id$q$,$q$do you store my passport$q$,$q$how long do you keep my id$q$,$q$will you keep my id$q$]::text[],$q$We collect your details only to review your application, run your account, pay you, prevent fraud and meet legal duties — and we **don't sell personal data**. Identity documents are kept in **private storage** (never in public folders), opened through short-lived links, and reviewed only by authorised staff with multi-factor authentication; access is logged. Data is encrypted in transit and protected by database access controls. No system is perfectly secure. Read the [Privacy Policy](/privacy.html) for full detail.$q$,array[$q$How long do you keep my data?$q$,$q$What are my data rights?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$data-retention-rights$q$,$q$privacy$q$,$q$How long do you keep my data? What are my data rights?$q$,array[$q$retention$q$,$q$how long do you keep$q$,$q$delete my data$q$,$q$data rights$q$,$q$subject access$q$,$q$erasure$q$,$q$right to be forgotten$q$,$q$access my data$q$,$q$gdpr rights$q$,$q$data request$q$,$q$remove my data$q$,$q$data deletion$q$,$q$copy of my data$q$,$q$keep my id forever$q$,$q$do you keep my documents$q$,$q$how long do you keep my documents$q$]::text[],$q$- **Retention:** documents for an application that's denied, withdrawn or never activated are scheduled for review after **12 months**; for an approved challenge, after **5 years** (or the end of our relationship if later), unless a legal hold or investigation applies.
- **Your rights (UK GDPR):** access your data, correct it, request erasure, object to or restrict processing, get a portable copy, and withdraw consent.

Exercise them by emailing {{c:contact_email}} from your registered address. Some records must be kept for legal, fraud-prevention or dispute purposes.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$cookies-analytics$q$,$q$privacy$q$,$q$What cookies do you use?$q$,array[$q$cookies$q$,$q$analytics$q$,$q$tracking$q$,$q$cookie settings$q$,$q$consent$q$,$q$cookie banner$q$,$q$do you track me$q$]::text[],$q$We use essential storage for security, sessions and your consent choices. **Optional analytics stay off until you choose "Accept analytics"**, and you can change your mind any time using **Cookie settings** in the page footer. See the [Privacy Policy](/privacy.html).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$account-security$q$,$q$privacy$q$,$q$How do I keep my account secure?$q$,array[$q$account security$q$,$q$hacked$q$,$q$someone accessed my account$q$,$q$compromised$q$,$q$2fa$q$,$q$two factor$q$,$q$share password$q$,$q$phishing$q$,$q$suspicious email$q$,$q$fake email$q$,$q$scam email$q$,$q$unauthorised access$q$,$q$secure my account$q$,$q$account stolen$q$,$q$someone logged into my account$q$,$q$someone else logged in$q$,$q$unauthorised login$q$,$q$unrecognised login$q$,$q$think i was hacked$q$,$q$i was hacked$q$]::text[],$q$- Never share your password, login or access with anyone — sharing an account breaches the Terms.
- **IPFX will never ask for your password** or ask you to pay outside our checkout. Beware of fake emails, DMs or "account managers" using our name.
- Use a strong, unique password and reset it from the [login page](/login.html) if in doubt.
- If you suspect unauthorised access, email {{c:contact_email}} **immediately** — you're responsible for safeguarding your credentials.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$who-processes-data$q$,$q$privacy$q$,$q$Who do you share my data with?$q$,array[$q$share my data$q$,$q$third parties$q$,$q$who processes$q$,$q$supabase$q$,$q$stripe$q$,$q$tradingview$q$,$q$data processors$q$,$q$international transfers$q$,$q$sell my data$q$,$q$data sharing$q$]::text[],$q$We share data only with providers needed to run the service — for example our database/authentication host (Supabase), our payment processor (Stripe, where enabled) and chart provider (where used) — and with law-enforcement or regulators where legally required. Where data leaves the UK we rely on adequacy decisions or standard contractual clauses. We don't sell your personal data. Details are in the [Privacy Policy](/privacy.html).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$contact$q$,$q$support$q$,$q$How do I contact IPFX support?$q$,array[$q$contact$q$,$q$email$q$,$q$support$q$,$q$help$q$,$q$customer service$q$,$q$human$q$,$q$speak to someone$q$,$q$talk to a person$q$,$q$phone number$q$,$q$call$q$,$q$live chat$q$,$q$agent$q$,$q$team$q$,$q$how do i reach$q$,$q$customer support$q$,$q$enquiries$q$,$q$inquiries$q$,$q$complaint$q$,$q$escalate$q$,$q$what is your email address$q$,$q$your email address$q$,$q$support email$q$,$q$what is your email$q$,$q$email address for support$q$,$q$how do i speak to a real person$q$,$q$speak to a real person$q$,$q$talk to a real person$q$,$q$do you have a phone number$q$,$q$live chat with a person$q$]::text[],$q$Email **{{c:contact_email}}** and the team will help. For account-specific issues please write from your registered email address and **don't include passwords, full card numbers or ID documents** in the email. You can also join the community on [Discord]({{c:discord_url}}) for general questions — but don't post account details there. Our [contact page]({{c:website}}/contact.html) form is launching in October 2026.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$technical-issue$q$,$q$support$q$,$q$The platform isn't working / I found a bug$q$,array[$q$bug$q$,$q$not working$q$,$q$error$q$,$q$platform down$q$,$q$can't place order$q$,$q$order rejected$q$,$q$won't load$q$,$q$glitch$q$,$q$technical problem$q$,$q$site down$q$,$q$cannot trade$q$,$q$stuck$q$,$q$crash$q$,$q$broken$q$,$q$outage$q$,$q$freezing$q$,$q$my order was rejected$q$,$q$order was rejected$q$,$q$orders are being rejected$q$]::text[],$q$Sorry about that. Quick checks: refresh the page, confirm you're logged in to the right account, and check whether the market is open (orders are rejected when a market is closed or no fresh price is available). Note that closing the browser doesn't close open positions. If it persists, email {{c:contact_email}} with the time, the account, the instrument, and what you saw. If you believe a platform fault materially affected your evaluation, the Terms let IPFX extend it or issue a replacement at its discretion (section 6.4).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$complaints-disputes$q$,$q$support$q$,$q$How do I make a complaint or dispute a decision?$q$,array[$q$complaint$q$,$q$complain$q$,$q$dispute$q$,$q$unfair$q$,$q$appeal decision$q$,$q$appeal breach$q$,$q$legal$q$,$q$solicitor$q$,$q$ombudsman$q$,$q$not happy$q$,$q$terminated unfairly$q$,$q$escalation$q$,$q$complaints procedure$q$,$q$complaint procedure$q$,$q$how do i complain$q$,$q$complaints process$q$,$q$what is your complaints procedure$q$]::text[],$q$Email {{c:contact_email}} with your registered email address, the account concerned and what you'd like reviewed. Decisions on rule breaches and prohibited practices are final under the Terms, but a written request will be reviewed at IPFX's discretion. The Terms (sections 19–20) set out governing law (England & Wales) and how disputes are handled. I can't give legal advice.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$dashboard-what$q$,$q$support$q$,$q$What's in my dashboard?$q$,array[$q$dashboard$q$,$q$where do i find$q$,$q$my account page$q$,$q$accounts page$q$,$q$where is my account$q$,$q$payouts page$q$,$q$how do i see my rules$q$,$q$login and find$q$,$q$my area$q$]::text[],$q$After logging in, your [dashboard](/dashboard.html) is where you can see your challenge accounts and their limits and progress, open IPFX Markets, submit or update your verification documents, request payouts, add payout methods and find your referral link. If something is missing, email {{c:contact_email}}.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$how-to-trade$q$,$q$trading$q$,$q$How do I place a trade on IPFX Markets?$q$,array[$q$how to trade$q$,$q$place an order$q$,$q$how do i place a trade$q$,$q$buy sell$q$,$q$market order$q$,$q$limit order$q$,$q$pending order$q$,$q$close trade$q$,$q$how do i close$q$,$q$set stop loss$q$,$q$set take profit$q$,$q$modify order$q$,$q$order types$q$]::text[],$q$Open IPFX Markets from your dashboard, choose your account and instrument, enter your size, set your stop-loss (required on some programmes) and optional take-profit, then place a market order or a pending limit/stop order. You can modify SL/TP, partially close, or close positions from the positions panel. All orders are checked against your rules before they fill. See "What are the execution costs?" for slippage and delay.$q$,array[$q$What is the stop-loss rule?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$about-bot$q$,$q$meta$q$,$q$Are you a real person? Who are you?$q$,array[$q$are you a bot$q$,$q$are you human$q$,$q$are you ai$q$,$q$real person$q$,$q$who am i talking to$q$,$q$are you a robot$q$,$q$chatbot$q$,$q$who are you really$q$,$q$artificial$q$,$q$are you a real person$q$,$q$is this a bot$q$,$q$am i talking to a bot$q$]::text[],$q$I'm IPFX's automated support assistant, not a person. I can answer questions about our programmes, rules, payouts and policies, but I can't see or change anyone's account. For anything personal or that I can't answer, email {{c:contact_email}}. Nothing I say is financial advice.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$what-can-you-do$q$,$q$meta$q$,$q$What can you help with?$q$,array[$q$what can you do$q$,$q$what can you help with$q$,$q$help me$q$,$q$what do you know$q$,$q$commands$q$,$q$topics$q$,$q$menu$q$,$q$options$q$]::text[],$q$I can help with: how IPFX works, the four programmes and their live fees and rules, applying and ID verification, trading rules and prohibited practices, payouts, refunds, referrals, data privacy and how to contact us. Try "What's the drawdown on the $50K Traditional?" or "How do payouts work?".$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$guarantee-profits$q$,$q$meta$q$,$q$Can I guarantee I'll pass or make money?$q$,array[$q$guarantee$q$,$q$guaranteed$q$,$q$will i pass$q$,$q$chance of passing$q$,$q$pass rate$q$,$q$success rate$q$,$q$how many pass$q$,$q$can i make money$q$,$q$is it easy$q$,$q$income$q$,$q$earn a living$q$,$q$how much can i make$q$,$q$get rich$q$,$q$passing percentage$q$,$q$win rate$q$,$q$what is the pass rate$q$,$q$what percent of people pass$q$,$q$percentage of people who pass$q$,$q$how many people pass$q$,$q$what percent pass$q$,$q$will i definitely get paid$q$,$q$definitely get paid if i pass$q$,$q$is payout guaranteed$q$]::text[],$q$No — nothing is guaranteed. We can't promise you'll pass a challenge, get funded or receive a payout, and past performance (including on simulated accounts) doesn't predict future results. We haven't published pass-rate statistics. Trading involves substantial risk; only pay what you can afford to lose and treat any payout as uncertain. See the [Risk Disclosure](/risk-disclosure.html).$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$financial-advice$q$,$q$meta$q$,$q$Can you give trading advice?$q$,array[$q$trading advice$q$,$q$financial advice$q$,$q$investment advice$q$,$q$trade tips$q$,$q$strategy advice$q$,$q$recommend a strategy$q$,$q$give me trading tips$q$,$q$trading tips$q$,$q$give me tips$q$]::text[],$q$I can't give investment or trading advice, signals or predictions — IPFX doesn't provide regulated financial advice and nothing on the site or in this chat is a recommendation. I *can* explain the rules so you can plan within them. For personal financial decisions, please speak to a qualified independent adviser.$q$,'{}'::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$time-limit$q$,$q$rules$q$,$q$Is there a time limit to pass a challenge?$q$,array[$q$time limit$q$,$q$is there a time limit$q$,$q$deadline$q$,$q$how long do i have to pass$q$,$q$how many days do i have$q$,$q$how many days do i have to hit the target$q$,$q$expire$q$,$q$expiry$q$,$q$expires$q$,$q$evaluation period$q$,$q$unlimited time$q$,$q$no time limit$q$,$q$30 day challenge$q$]::text[],$q$- **Traditional and Futures:** there's **no time limit** to pass a phase. You must still meet the minimum trading days and trades, and every rule applies at all times.
- **Infinity:** none of the published rules includes a deadline; the limit that applies is the number of Stage 1 attempts per calendar month ({{p:infinity_s1.attempts}}).
- **PAC:** the evaluation window (standard, extended or unlimited) is agreed with you.$q$,array[$q$What are the minimum trading days?$q$,$q$What are the profit targets?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$how-ipfx-makes-money$q$,$q$company$q$,$q$How does IPFX make money?$q$,array[$q$how do you make money$q$,$q$how does ipfx make money$q$,$q$business model$q$,$q$where does the money come from$q$,$q$where does my fee go$q$,$q$what do you do with my fee$q$,$q$how do you profit$q$,$q$how are you funded$q$,$q$what is your business model$q$]::text[],$q$Challenge fees fund the risk pool used to back funded accounts, and part of each fee covers platform and operating costs. When a funded trader is profitable, they keep {{p:trad_25k_p1.split_pct}} of the profit and IPFX keeps the rest. I can't share internal financials or risk models — the [About page](/about.html) describes how we run things.$q$,array[$q$How do payouts work?$q$,$q$Is the fee refundable?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$trading-data-use$q$,$q$privacy$q$,$q$Who can see my trades? Do you use my trading data?$q$,array[$q$who can see my trades$q$,$q$do you use my trades$q$,$q$trading data$q$,$q$do you copy my trades$q$,$q$do you mirror my trades$q$,$q$do you trade against me$q$,$q$who sees my trading$q$,$q$is my strategy private$q$,$q$do you steal strategies$q$,$q$do you share my strategy$q$,$q$trade data privacy$q$,$q$my strategy confidential$q$]::text[],$q$We record the trading data on your accounts (orders, sizes, prices, timings, balance history). It's used to run your account, calculate your results and payouts, enforce the rules and detect prohibited practices, and — in **aggregated, anonymised** form — to calibrate our risk models and improve the platform.

Under our Terms (section 11) we do **not** place, mirror or copy trades on any live account based on your individual, identifiable trading data. Any future programme that did would be a separate, clearly described opt-in with its own terms and compensation. For the PAC, your strategy disclosure is treated as confidential. See the [Privacy Policy](/privacy.html).$q$,array[$q$Is my ID safe?$q$,$q$How long do you keep my data?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
insert into public.support_kb(id,topic,title,keywords,answer,follow_ups) values($q$launch-status$q$,$q$company$q$,$q$When does IPFX launch? Is it live yet?$q$,array[$q$when do you launch$q$,$q$when does ipfx launch$q$,$q$are you live$q$,$q$is it live$q$,$q$open yet$q$,$q$launching october$q$,$q$launch date$q$,$q$pre-register$q$,$q$pre register$q$,$q$coming soon$q$,$q$when will it open$q$,$q$is ipfx open$q$,$q$is the site live$q$,$q$when can i start$q$,$q$are you open$q$,$q$is the faq available$q$,$q$is the contact form live$q$]::text[],$q${{c:launch_note}}$q$,array[$q$How do I start?$q$,$q$Is the Infinity Challenge free?$q$]::text[]) on conflict (id) do update set topic=excluded.topic,title=excluded.title,keywords=excluded.keywords,answer=excluded.answer,follow_ups=excluded.follow_ups,updated_at=now() where public.support_kb.edited_by_owner=false;
